    21  extern "C" int LLVMFuzzerTestOneInput(const unsigned char *Data,
    22                                        unsigned Size) {
    23    if (Size >= 4095) {
    24      return 0;
    25    }
    26    char Buffer[Size + 1];
    27    std::memcpy(Buffer, Data, Size);
    28    Buffer[Size] = 0;
    29    char demangled[4096];
    30    google::Demangle(Buffer, demangled, Size);
    31    return 0;
    32  }
